sys_script_include.script:
var IntegrationRegistry = Class.create();

// Default local implementations, used when no active integration_provider row
// exists for an aggregate. Adding an external system is a row, not a code change.
IntegrationRegistry.LOCAL_DEFAULTS = {
    rating: 'LocalRatingProvider',
    policy: 'LocalPolicyProvider'
};

IntegrationRegistry.prototype = {

    initialize: function () {
        this._cache = {};
    },

    // Active provider row for an aggregate: lowest priority wins, default breaks ties.
    getProviderRecord: function (aggregate) {
        var gr = new GlideRecord(Constants.TABLE.INTEGRATION_PROVIDER);
        gr.addQuery('aggregate', aggregate);
        gr.addQuery('active', true);
        gr.orderBy('priority');
        gr.orderByDesc('is_default');
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr : null;
    },

    // Returns an object exposing the aggregate's provider contract.
    //   script_include  -> an instance of that class (same scope)
    //   rest_message    -> a proxy: call(httpMethodName, params) -> parsed JSON
    //   integration_hub -> a proxy: call(actionScopedName, inputs) -> outputs
    getProvider: function (aggregate) {
        if (this._cache[aggregate])
            return this._cache[aggregate];

        var row = this.getProviderRecord(aggregate);
        var type = row ? String(row.getValue('implementation_type')) : Constants.CHOICE.IMPLEMENTATION_TYPE.SCRIPT_INCLUDE;
        var impl = row ? String(row.getValue('implementation') || '') : (IntegrationRegistry.LOCAL_DEFAULTS[aggregate] || '');
        if (!impl)
            throw new Error('[IntegrationRegistry] no provider configured for aggregate ' + aggregate);

        var provider;
        if (type === Constants.CHOICE.IMPLEMENTATION_TYPE.SCRIPT_INCLUDE)
            provider = this._instantiate(impl);
        else if (type === Constants.CHOICE.IMPLEMENTATION_TYPE.REST_MESSAGE)
            provider = this._restProxy(impl);
        else
            provider = this._flowActionProxy(impl);

        provider.providerSysId = row ? row.getUniqueValue() : '';
        this._cache[aggregate] = provider;
        return provider;
    },

    _instantiate: function (impl) {
        var name = impl.indexOf('.') > -1 ? impl.split('.').pop() : impl;
        var ctor = x_gegis_ins_policy[name];
        if (typeof ctor !== 'function')
            throw new Error('[IntegrationRegistry] script include not found: ' + impl);
        return new ctor();
    },

    _restProxy: function (restMessageName) {
        return {
            type: 'rest_message',
            call: function (httpMethodName, params) {
                var rm = new sn_ws.RESTMessageV2(restMessageName, httpMethodName);
                for (var k in (params || {})) {
                    if (params.hasOwnProperty(k))
                        rm.setStringParameterNoEscape(k, String(params[k]));
                }
                if (params && params.body)
                    rm.setRequestBody(typeof params.body === 'string' ? params.body : JSON.stringify(params.body));
                var res = rm.execute();
                var status = res.getStatusCode();
                if (status < 200 || status >= 300)
                    throw new Error('[IntegrationRegistry] ' + restMessageName + '.' + httpMethodName + ' HTTP ' + status);
                var body = res.getBody();
                return body ? JSON.parse(body) : {};
            }
        };
    },

    _flowActionProxy: function (actionScopedName) {
        return {
            type: 'integration_hub',
            call: function (inputs) {
                return sn_fd.FlowAPI.getRunner().action(actionScopedName).inForeground().withInputs(inputs || {}).run().getOutputs();
            }
        };
    },

    type: 'IntegrationRegistry'
};
